    const permissionsWithToken = clampedPermissions.map((perm)=>permissionDomain.create({
            ...perm,
            apiToken: tokenId,
            role: null
        }));
    const existingPermissions = await getService('permission').findMany({
        where: {
            apiToken: {
                id: tokenId
            }
        }
    });
    const permissionsToAdd = differenceWith(permissionsWithToken, existingPermissions, arePermissionsEqual);
    const permissionsToDelete = differenceWith(existingPermissions, permissionsWithToken, arePermissionsEqual);
